@@ -0,0 +1,261 @@
+/**
+ * Unit tests for the executor adapter factory (T1 — EXECUTOR_TYPE / EXECUTOR_PROFILE).
+ *
+ * Tests cover:
+ *   1. resolveExecutorBin — claude and hermes paths, default and explicit dist
+ *   2. resolveExecutorEnv — hermes env vars, optional fields, claude no-op
+ *   3. createExecutorAdapter — profile switch, type routing, unknown profile throws
+ *   4. Env var precedence: EXECUTOR_PROFILE + EXECUTOR_TYPE read from process.env
+ */
+
+import { describe, it, expect, afterEach } from "vitest";
+import * as path from "node:path";
+
+import {
+  resolveExecutorBin,
+  resolveExecutorEnv,
+  createExecutorAdapter,
+  type ExecutorFactoryConfig,
+} from "../src/adapters/executor-factory.js";
+import { SubProcessAdapter } from "../src/adapters/executor/subprocess.js";
+
+// ── Helpers ───────────────────────────────────────────────────────────────────
+
+function withEnv(vars: Record<string, string | undefined>, fn: () => void): void {
+  const originals: Record<string, string | undefined> = {};
+  for (const [k, v] of Object.entries(vars)) {
+    originals[k] = process.env[k];
+    if (v === undefined) {
+      delete process.env[k];
+    } else {
+      process.env[k] = v;
+    }
+  }
+  try {
+    fn();
+  } finally {
+    for (const [k, original] of Object.entries(originals)) {
+      if (original === undefined) {
+        delete process.env[k];
+      } else {
+        process.env[k] = original;
+      }
+    }
+  }
+}
+
+afterEach(() => {
+  delete process.env.EXECUTOR_PROFILE;
+  delete process.env.EXECUTOR_TYPE;
+  delete process.env.EXECUTOR_BIN_PREFIX;
+});
+
+// ── 1. resolveExecutorBin ──────────────────────────────────────────────────────
+
+describe("resolveExecutorBin", () => {
+  it("returns default claude path under EXECUTOR_BIN_PREFIX when no override", () => {
+    withEnv({ EXECUTOR_BIN_PREFIX: "/custom-prefix" }, () => {
+      const bin = resolveExecutorBin("claude", {});
+      expect(bin).toBe(
+        path.join("/custom-prefix", "runtime", "executors", "claude", "dist", "index.js"),
+      );
+    });
+  });
+
+  it("returns default hermes path under EXECUTOR_BIN_PREFIX when no override", () => {
+    withEnv({ EXECUTOR_BIN_PREFIX: "/custom-prefix" }, () => {
+      const bin = resolveExecutorBin("hermes", {});
+      expect(bin).toBe(
+        path.join("/custom-prefix", "runtime", "executors", "hermes", "dist", "index.js"),
+      );
+    });
+  });
+
+  it("uses explicit claudeExecutorDist when provided", () => {
+    const config: ExecutorFactoryConfig = { claudeExecutorDist: "/explicit/claude/dist" };
+    const bin = resolveExecutorBin("claude", config);
+    expect(bin).toBe("/explicit/claude/dist/index.js");
+  });
+
+  it("uses explicit hermesExecutorDist when provided", () => {
+    const config: ExecutorFactoryConfig = { hermesExecutorDist: "/explicit/hermes/dist" };
+    const bin = resolveExecutorBin("hermes", config);
+    expect(bin).toBe("/explicit/hermes/dist/index.js");
+  });
+
+  it("defaults to claude path for unknown executor type", () => {
+    const config: ExecutorFactoryConfig = { claudeExecutorDist: "/claude/dist" };
+    const bin = resolveExecutorBin("unknown-type", config);
+    expect(bin).toBe("/claude/dist/index.js");
+  });
+
+  it("falls back to /workflow prefix when EXECUTOR_BIN_PREFIX is not set", () => {
+    withEnv({ EXECUTOR_BIN_PREFIX: undefined }, () => {
+      const bin = resolveExecutorBin("claude", {});
+      expect(bin).toBe(
+        path.join("/workflow", "runtime", "executors", "claude", "dist", "index.js"),
+      );
+    });
+  });
+});
+
+// ── 2. resolveExecutorEnv ──────────────────────────────────────────────────────
+
+describe("resolveExecutorEnv", () => {
+  it("returns empty object for claude type", () => {
+    const env = resolveExecutorEnv("claude", {});
+    expect(env).toEqual({});
+  });
+
+  it("returns empty object for unknown type (defaults to claude)", () => {
+    const env = resolveExecutorEnv("anything", {});
+    expect(env).toEqual({});
+  });
+
+  it("returns hermes required env vars with empty strings when missing from config", () => {
+    const env = resolveExecutorEnv("hermes", {});
+    expect(env).toHaveProperty("HERMES_INFERENCE_MODEL", "");
+    expect(env).toHaveProperty("HERMES_INFERENCE_PROVIDER", "");
+    expect(env).toHaveProperty("DEEPSEEK_API_KEY", "");
+  });
+
+  it("populates hermes env vars from config", () => {
+    const config: ExecutorFactoryConfig = {
+      hermesModel: "deepseek-v4-flash",
+      hermesProvider: "deepseek",
+      deepseekApiKey: "sk-test-key",
+    };
+    const env = resolveExecutorEnv("hermes", config);
+    expect(env.HERMES_INFERENCE_MODEL).toBe("deepseek-v4-flash");
+    expect(env.HERMES_INFERENCE_PROVIDER).toBe("deepseek");
+    expect(env.DEEPSEEK_API_KEY).toBe("sk-test-key");
+  });
+
+  it("omits RAG_MCP_URL when not provided", () => {
+    const env = resolveExecutorEnv("hermes", {});
+    expect(env).not.toHaveProperty("RAG_MCP_URL");
+  });
+
+  it("includes RAG_MCP_URL and RAG_MCP_TOKEN when provided", () => {
+    const config: ExecutorFactoryConfig = {
+      ragMcpUrl: "http://rag:8080",
+      ragMcpToken: "bearer-token",
+    };
+    const env = resolveExecutorEnv("hermes", config);
+    expect(env.RAG_MCP_URL).toBe("http://rag:8080");
+    expect(env.RAG_MCP_TOKEN).toBe("bearer-token");
+  });
+
+  it("omits RAG_MCP_TOKEN when not provided (even if URL is set)", () => {
+    const config: ExecutorFactoryConfig = { ragMcpUrl: "http://rag:8080" };
+    const env = resolveExecutorEnv("hermes", config);
+    expect(env.RAG_MCP_URL).toBe("http://rag:8080");
+    expect(env).not.toHaveProperty("RAG_MCP_TOKEN");
+  });
+
+  it("includes HERMES_MAX_TURNS when hermesMaxTurns is set", () => {
+    const config: ExecutorFactoryConfig = { hermesMaxTurns: 200 };
+    const env = resolveExecutorEnv("hermes", config);
+    expect(env.HERMES_MAX_TURNS).toBe("200");
+  });
+
+  it("omits HERMES_MAX_TURNS when hermesMaxTurns is not set", () => {
+    const env = resolveExecutorEnv("hermes", {});
+    expect(env).not.toHaveProperty("HERMES_MAX_TURNS");
+  });
+});
+
+// ── 3. createExecutorAdapter ───────────────────────────────────────────────────
+
+describe("createExecutorAdapter", () => {
+  it("returns a SubProcessAdapter for local-subprocess profile (default)", () => {
+    withEnv({ EXECUTOR_PROFILE: undefined, EXECUTOR_TYPE: undefined }, () => {
+      const adapter = createExecutorAdapter({
+        claudeExecutorDist: "/claude/dist",
+      });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+
+  it("returns a SubProcessAdapter when EXECUTOR_PROFILE=local-subprocess", () => {
+    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "claude" }, () => {
+      const adapter = createExecutorAdapter({ claudeExecutorDist: "/claude/dist" });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+
+  it("returns a SubProcessAdapter for hermes type on local-subprocess profile", () => {
+    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "hermes" }, () => {
+      const adapter = createExecutorAdapter({
+        hermesExecutorDist: "/hermes/dist",
+        hermesModel: "deepseek-v4-flash",
+        hermesProvider: "deepseek",
+        deepseekApiKey: "sk-test",
+      });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+
+  it("throws for unknown EXECUTOR_PROFILE", () => {
+    withEnv({ EXECUTOR_PROFILE: "unknown-profile" }, () => {
+      expect(() => createExecutorAdapter({})).toThrow(
+        "Unknown EXECUTOR_PROFILE: unknown-profile",
+      );
+    });
+  });
+
+  it("adapter supervisionSize starts at 0 (no submissions yet)", () => {
+    withEnv({ EXECUTOR_PROFILE: undefined, EXECUTOR_TYPE: undefined }, () => {
+      const adapter = createExecutorAdapter({ claudeExecutorDist: "/claude/dist" });
+      expect((adapter as SubProcessAdapter).supervisionSize()).toBe(0);
+    });
+  });
+
+  it("merges extraEnv from config into the subprocess adapter env", () => {
+    // Verify that the factory correctly threads extraEnv through.
+    // We can only inspect this indirectly — the adapter should construct without error
+    // when extraEnv contains task-specific vars.
+    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "claude" }, () => {
+      const adapter = createExecutorAdapter({
+        claudeExecutorDist: "/claude/dist",
+        extraEnv: { TASK_BRANCH: "feature/foo", MAX_TURNS: "50" },
+      });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+
+  it("hermes executor-type env takes lower precedence than caller extraEnv", () => {
+    // The factory merges resolveExecutorEnv FIRST, then extraEnv on top.
+    // Callers can override hermes defaults by setting the same key in extraEnv.
+    // This is a design invariant — test it structurally via the factory call succeeding.
+    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "hermes" }, () => {
+      const adapter = createExecutorAdapter({
+        hermesExecutorDist: "/hermes/dist",
+        hermesModel: "base-model",
+        hermesProvider: "deepseek",
+        deepseekApiKey: "sk-test",
+        // Caller overrides the model via extraEnv
+        extraEnv: { HERMES_INFERENCE_MODEL: "override-model" },
+      });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+});
+
+// ── 4. Env var defaults ────────────────────────────────────────────────────────
+
+describe("EXECUTOR_PROFILE and EXECUTOR_TYPE defaults", () => {
+  it("EXECUTOR_PROFILE defaults to local-subprocess when unset", () => {
+    withEnv({ EXECUTOR_PROFILE: undefined }, () => {
+      // Should not throw — local-subprocess is the default
+      expect(() => createExecutorAdapter({ claudeExecutorDist: "/claude/dist" })).not.toThrow();
+    });
+  });
+
+  it("EXECUTOR_TYPE defaults to claude when unset", () => {
+    withEnv({ EXECUTOR_TYPE: undefined }, () => {
+      const adapter = createExecutorAdapter({ claudeExecutorDist: "/explicit/claude" });
+      expect(adapter).toBeInstanceOf(SubProcessAdapter);
+    });
+  });
+});

